(function() {
	//#region src/Modules/CrestApps.OrchardCore.Telephony/Assets/js/phone-field-dialer.js
	(function() {
		"use strict";
		function getConfig() {
			return window.__telephonyPhoneFieldDialer || null;
		}
		function getNumber(placeholder) {
			if (placeholder.hasAttribute("data-phone-number")) return (placeholder.getAttribute("data-phone-number") || "").trim();
			var field = placeholder.closest("[data-phone-field]");
			if (field) {
				var e164 = field.querySelector("[data-phone-e164]");
				if (e164 && e164.value) return e164.value.trim();
				var tel = field.querySelector("input[type=\"tel\"]");
				if (tel && tel.value) return tel.value.trim();
			}
			return "";
		}
		function createButton() {
			var button = document.createElement("button");
			button.type = "button";
			button.className = "btn btn-sm btn-outline-success telephony-phone-dial-btn ms-1";
			button.title = "Call with the soft phone";
			button.innerHTML = "<i class=\"fa-solid fa-phone\"></i>";
			return button;
		}
		function flash(button, iconClass, revertMs) {
			var original = button.innerHTML;
			button.innerHTML = "<i class=\"" + iconClass + "\"></i>";
			setTimeout(function() {
				button.innerHTML = original;
			}, revertMs || 1500);
		}
		function dial(button, number) {
			var config = getConfig();
			if (!config || !config.dialUrl) return;
			button.disabled = true;
			var body = new URLSearchParams();
			body.append("number", number);
			var headers = { "X-Requested-With": "XMLHttpRequest" };
			if (config.antiforgeryToken) headers["RequestVerificationToken"] = config.antiforgeryToken;
			fetch(config.dialUrl, {
				method: "POST",
				credentials: "same-origin",
				headers,
				body
			}).then(function(response) {
				button.disabled = false;
				if (response.ok) flash(button, "fa-solid fa-check");
				else flash(button, "fa-solid fa-triangle-exclamation");
			}).catch(function() {
				button.disabled = false;
				flash(button, "fa-solid fa-triangle-exclamation");
			});
		}
		function enhance(placeholder) {
			if (placeholder.__telephonyEnhanced) return;
			placeholder.__telephonyEnhanced = true;
			var button = createButton();
			button.addEventListener("click", function() {
				var number = getNumber(placeholder);
				if (number) dial(button, number);
			});
			placeholder.appendChild(button);
		}
		function enhanceAll() {
			var placeholders = document.querySelectorAll("[data-phone-dial]");
			Array.prototype.forEach.call(placeholders, enhance);
		}
		if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", enhanceAll);
		else enhanceAll();
	})();
	//#endregion
})();
